import json,sys,re
hits=[]
for l in open(sys.argv[1]):
    try: e=json.loads(l)
    except: continue
    if e.get('type')!='assistant': continue
    for c in e.get('message',{}).get('content',[]):
        t=c.get('text') or ''
        for m in re.finditer(r'[^\n]{0,200}\b\d{1,3} ?%[^\n]{0,200}', t):
            if re.search(r'align|diverg|similar|agree|match|overlap|within|differ', m.group(0), re.I): hits.append((e.get('timestamp'),m.group(0)))
if hits:
    print('==',sys.argv[1])
    for ts,h in hits[-12:]: print(' ',ts,h)
E
done

