cd /home/hyphyphyph/piton/repl; ls -t .suspense/divergence | head -3; python3 - <<'E'
import json,glob,os
f=sorted(glob.glob('.suspense/divergence/*.json'),key=os.path.getmtime)[-1]
d=json.load(open(f))
vals=[]
def walk(o):
    if isinstance(o,dict):
        if 'divergence' in o and isinstance(o['divergence'],(int,float)): vals.append(o['divergence'])
        for v in o.values(): walk(v)
    elif isinstance(o,list):
        for v in o: walk(v)
walk(d)
print(f, len(vals), 'files; mean', round(sum(vals)/len(vals),3) if vals else None, 'max', max(vals) if vals else None)
E

